<script setup>
import { ref, computed, nextTick } from 'vue';
import { Network, LayoutDashboard, Map, Boxes, ArrowUpRight, ArrowRight, Search, Radio, Server, Cable, GitBranch, Router, X, ChevronRight, Download, BookOpen, Check, ZoomIn, ZoomOut } from 'lucide-vue-next';
import data from './data.json';
const mapUrl = `${import.meta.env.BASE_URL}mapeo_red_ftth.png`;
const query = ref('');
const filter = ref('Todos');
const selected = ref(null);
const tab = ref('Descripción');
const dialog = ref(null);
const mapZoom = ref(false);
const activeNav = ref('overview');
let previousFocus;
const components = [
 { key:'olt',name:'OLT',subtitle:'Terminal de línea óptica',type:'Activo',icon:Server,tone:'purple',metric:'2,488 Gbps',location:'Central'},
 { key:'odf',name:'ODF',subtitle:'Distribución óptica',type:'Pasivo',icon:Boxes,tone:'blue',metric:'288 fibras',location:'Central'},
 { key:'feeder',name:'Feeder',subtitle:'Cable alimentador',type:'Pasivo',icon:Cable,tone:'peach',metric:'G.652D',location:'Red exterior'},
 { key:'fosc',name:'FOSC',subtitle:'Cierre de empalme óptico',type:'Pasivo',icon:Radio,tone:'mint',metric:'144 empalmes',location:'Red exterior'},
 { key:'splitter',name:'Splitter',subtitle:'Divisor óptico PLC',type:'Pasivo',icon:GitBranch,tone:'pink',metric:'1:32',location:'Distribución'},
 { key:'ont',name:'ONT',subtitle:'Terminal de red óptica',type:'Activo',icon:Router,tone:'yellow',metric:'4 × Gigabit',location:'Usuario final'}
];
const filtered = computed(() => components.filter(c => (filter.value==='Todos'||c.type===filter.value) && `${c.name} ${c.subtitle} ${data[c.key].description} ${c.metric}`.toLowerCase().includes(query.value.toLowerCase())));
const current = computed(()=>selected.value ? data[selected.value.key]:null);
const tabs = ['Descripción','Especificaciones','Normas','Notas'];
const zones = [{key:'olt',top:11,left:2,width:21,height:26},{key:'odf',top:12,left:24,width:9,height:20},{key:'feeder',top:57,left:27,width:18,height:20},{key:'fosc',top:22,left:47,width:9,height:22},{key:'splitter',top:51,left:51,width:14,height:23},{key:'ont',top:10,left:84,width:14,height:18},{key:'ont',top:62,left:84,width:14,height:20}];
async function open(c){ previousFocus=document.activeElement; selected.value=c;tab.value='Descripción';await nextTick();dialog.value.showModal(); }
function close(){dialog.value.close();selected.value=null;previousFocus?.focus();}
function navigate(id){ activeNav.value=id;document.getElementById(id)?.scrollIntoView({behavior:'smooth'}); }
function exportSheet(){const c=current.value;const text=[c.title,c.tags,'',c.description,'',...c.specs.map(r=>r.join(': ')),'',...c.features,'',...c.standards,'',c.notes].join('\n'); const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`ficha-${selected.value.key}.txt`;a.click();URL.revokeObjectURL(url);}
function tabKeys(event){const i=tabs.indexOf(tab.value);if(['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();tab.value=tabs[event.key==='Home'?0:event.key==='End'?3:(i+(event.key==='ArrowRight'?1:3))%4];nextTick(()=>document.getElementById('tab-'+tab.value)?.focus());}}
</script>

<template>
<div class="app-shell">
<aside class="sidebar">
<a class="brand" href="#overview" @click="activeNav='overview'"><span class="brand-icon"><Network :size="25"/></span><span>fibra<span class="brand-light">lab</span><small>EXPLORADOR FTTH</small></span></a>
<div class="nav-label">ESPACIO DE APRENDIZAJE</div>
<nav aria-label="Navegación principal">
<button :class="{active:activeNav==='overview'}" @click="navigate('overview')"><LayoutDashboard :size="19"/> Vista general</button>
<button :class="{active:activeNav==='architecture'}" @click="navigate('architecture')"><Map :size="19"/> Arquitectura de red</button>
<button :class="{active:activeNav==='components'}" @click="navigate('components')"><Boxes :size="19"/> Componentes <span class="count">6</span></button>
</nav>
<div class="side-note"><span class="tiny-icon"><BookOpen :size="22"/></span><h3>Del concepto a la conexión.</h3><p>Explora cada elemento y entiende cómo viaja la señal hasta tu hogar.</p><button @click="navigate('signal')">Ver el recorrido <ArrowRight :size="16"/></button></div>
<div class="sidebar-footer"><span class="status-dot"></span> Biblioteca técnica FTTH <small>GPON · Red de acceso óptico</small></div>
</aside>
<div class="workspace">
<header class="topbar"><div>Espacio de aprendizaje <ChevronRight :size="14"/> <strong>Vista general</strong></div><span class="top-badge"><span class="status-dot"></span> Arquitectura GPON</span></header>
<main id="overview">
<div class="page-heading"><div><p class="eyebrow">CONECTA CON EL CONOCIMIENTO</p><h1>Una red. Infinitas conexiones<span>.</span></h1><p>Descubre la fibra óptica, desde la central hasta el hogar.</p></div><span class="edition">GUÍA INTERACTIVA <span>01 / FTTH</span></span></div>
<section class="hero-card">
<div class="hero-copy"><span class="pill"><span class="status-dot"></span> FIBER TO THE HOME</span><h2>La conexión empieza<br>con una buena <em>base.</em></h2><p>Entiende la arquitectura FTTH y explora los componentes que hacen posible una red de fibra óptica.</p><button class="primary" @click="navigate('architecture')">Explorar la red <ArrowUpRight :size="18"/></button><span class="hero-caption">6 componentes · Fichas técnicas detalladas</span></div>
<div class="hero-visual" aria-hidden="true"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="visual-label label-one">CENTRAL</span><span class="visual-label label-two">TU HOGAR</span><div class="clay-node central"><Server :size="61" stroke-width="1.5"/><span>OLT</span><div class="leds"><i></i><i></i><i></i></div></div><div class="connection"><span></span><span></span><span></span></div><div class="clay-node home"><Router :size="58" stroke-width="1.5"/><span>ONT</span></div><div class="floating-tag"><span class="status-dot"></span> Conectados por luz</div><div class="spark">✦</div></div>
</section>
<div class="stats-grid"><article><span class="stat-icon purple"><Boxes/></span><div><strong>6 <small>componentes</small></strong><p>De la central al abonado</p></div></article><article><span class="stat-icon mint"><GitBranch/></span><div><strong>1:32 <small>división óptica</small></strong><p>Arquitectura punto a multipunto</p></div></article><article><span class="stat-icon peach"><Cable/></span><div><strong>GPON <small>tecnología</small></strong><p>Acceso mediante fibra óptica</p></div></article></div>
<section id="architecture" class="section"><div class="section-heading"><div><p class="eyebrow">EL PANORAMA COMPLETO</p><h2>Arquitectura de la red</h2><p>Selecciona un elemento del mapa para conocerlo en detalle.</p></div><button class="secondary zoom-button" @click="mapZoom=!mapZoom"><component :is="mapZoom?ZoomOut:ZoomIn" :size="17"/> {{mapZoom?'Reducir':'Ampliar mapa'}}</button></div><div class="map-card"><div class="map-toolbar"><span><span class="status-dot"></span> Topología FTTH</span><span>MAPA INTERACTIVO <Map :size="15"/></span></div><div class="map-scroll" :class="{zoomed:mapZoom}"><div class="map-image"><img :src="mapUrl" alt="Diagrama de la red FTTH: OLT, ODF, feeder, FOSC, splitter y terminales ONT"><button v-for="(z,i) in zones" :key="i" class="map-zone" :style="{top:z.top+'%',left:z.left+'%',width:z.width+'%',height:z.height+'%'}" :aria-label="'Ver ficha de '+z.key.toUpperCase()" @click="open(components.find(c=>c.key===z.key))"><span>{{z.key.toUpperCase()}} <ArrowUpRight :size="12"/></span></button></div></div><div class="map-legend"><span><i class="legend-dot down"></i>1490 nm · Descendente</span><span><i class="legend-dot up"></i>1310 nm · Ascendente</span><span><i class="legend-dot video"></i>1550 nm · Vídeo RF opcional</span><small>Haz clic para explorar <ArrowUpRight :size="13"/></small></div></div></section>
<section id="signal" class="section signal-section"><div class="section-heading"><div><p class="eyebrow">PASO A PASO</p><h2>El viaje de la señal</h2><p>Un recorrido desde la central hasta el usuario final.</p></div><span class="subtle-badge">SENTIDO DESCENDENTE <ArrowRight :size="14"/></span></div><div class="signal-flow"><template v-for="(c,i) in components" :key="c.key"><button @click="open(c)"><span class="step-icon" :class="c.tone"><component :is="c.icon" :size="25"/></span><strong>{{c.name}}</strong><small>{{c.location}}</small><span class="step-number">0{{i+1}}</span></button><ChevronRight v-if="i<5" class="flow-arrow" :size="19"/></template></div><p class="flow-note">Entre el splitter y la ONT, la señal viaja por el cable de distribución y la acometida del abonado.</p></section>
<section id="components" class="section"><div class="section-heading"><div><p class="eyebrow">CONOCE CADA PIEZA</p><h2>Biblioteca de componentes</h2><p>Todo lo que necesitas saber, en un solo lugar.</p></div><span class="subtle-badge">{{filtered.length}} DE 6 COMPONENTES</span></div><div class="library-tools"><div class="filters" aria-label="Filtrar componentes"><button v-for="f in ['Todos','Activo','Pasivo']" :key="f" @click="filter=f" :class="{selected:filter===f}" :aria-pressed="filter===f">{{f==='Todos'?'Todos':f==='Activo'?'Activos':'Pasivos'}}</button></div><label class="search"><Search :size="18"/><input v-model="query" type="search" placeholder="Buscar componente…" aria-label="Buscar componente"/></label></div><div class="component-grid"><button v-for="c in filtered" :key="c.key" class="component-card" @click="open(c)"><div class="card-top"><span class="component-icon" :class="c.tone"><component :is="c.icon" :size="32" stroke-width="1.6"/></span><span class="type-badge" :class="{isactive:c.type==='Activo'}">{{c.type}}</span></div><h3>{{c.name}}</h3><p>{{c.subtitle}}</p><div class="card-bottom"><span>{{c.metric}}</span><span class="open-icon"><ArrowUpRight :size="18"/></span></div></button></div><div v-if="!filtered.length" class="empty"><Search :size="30"/><h3>No encontramos componentes</h3><p>Prueba con OLT, fibra o splitter.</p><button class="secondary" @click="query='';filter='Todos'">Restablecer búsqueda</button></div></section>
<footer><span class="footer-brand"><Network :size="18"/> fibra<strong>lab</strong></span><p>Biblioteca educativa · Valores de referencia sujetos al equipo y al diseño de red.</p><span>HECHO PARA APRENDER</span></footer>
</main>
</div>
<dialog ref="dialog" @cancel.prevent="close" @click="e=>{if(e.target===dialog)close()}" aria-labelledby="detail-title"><template v-if="current"><div class="dialog-heading"><span class="component-icon" :class="selected.tone"><component :is="selected.icon" :size="28"/></span><button class="close-button" @click="close" aria-label="Cerrar ficha"><X :size="21"/></button><p class="eyebrow">FICHA DEL COMPONENTE · {{selected.type.toUpperCase()}}</p><h2 id="detail-title">{{current.title}}</h2><p>{{current.tags}}</p></div><div class="tabs" role="tablist" aria-label="Información del componente" @keydown="tabKeys"><button v-for="t in tabs" :id="'tab-'+t" :key="t" role="tab" :aria-selected="tab===t" :tabindex="tab===t?0:-1" aria-controls="detail-panel" :class="{active:tab===t}" @click="tab=t">{{t}}</button></div><div class="dialog-content" id="detail-panel" role="tabpanel" :aria-labelledby="'tab-'+tab" tabindex="0"><template v-if="tab==='Descripción'"><h3>Descripción general</h3><p>{{current.description}}</p><h3>Longitudes de onda</h3><div class="wavelengths"><span v-for="w in current.wavelengths" :key="w.nm"><i :style="{background:w.color}"></i><strong>{{w.nm}}</strong>{{w.dir}}</span></div><a v-if="current.downloadUrl" class="secondary source-link" :href="current.downloadUrl" target="_blank" rel="noopener noreferrer"><Download :size="15"/> Documento original de OLT</a><h3>Características principales</h3><ul><li v-for="f in current.features" :key="f"><Check :size="16"/>{{f}}</li></ul></template><template v-else-if="tab==='Especificaciones'"><h3>Especificaciones de referencia</h3><div class="table-scroll"><table><tbody><tr v-for="row in current.specs" :key="row[0]"><th scope="row">{{row[0]}}</th><td>{{row[1]}}</td></tr></tbody></table></div></template><template v-else-if="tab==='Normas'"><h3>Normas y estándares</h3><div class="standards"><span v-for="s in current.standards" :key="s"><BookOpen :size="18"/>{{s}}</span></div><p class="reference-note">Referencias conservadas de la biblioteca original. Las especificaciones dependen del fabricante y de la configuración.</p></template><template v-else><h3>Notas de ingeniería</h3><p>{{current.notes}}</p></template></div><div class="dialog-footer"><span>Información técnica de referencia</span><button class="primary" @click="exportSheet"><Download :size="16"/> Exportar ficha</button></div></template></dialog>
</div>
</template>
